// billing/invoice.ts
const SALE_END = new Date("2026-05-31T23:59:59Z");

export function calculateTotal(subtotalCents: number): number {
  const discount = new Date() <= SALE_END ? 0.1 : 0;
  return Math.round(subtotalCents * (1 - discount));
}
```

