Title: "Add Redis cache for product lookups"
Body: "Adds a Redis cache in front of ProductRepository.getById with a 10 minute TTL."

```ts
export class CachedProductRepository {
  constructor(private redis: Redis, private inner: ProductRepository) {}
  async getById(id: string) {
    const hit = await this.redis.get(`product:${id}`);
    if (hit) return JSON.parse(hit);
    const p = await this.inner.getById(id);
    await this.redis.set(`product:${id}`, JSON.stringify(p), "EX", 600);
    return p;
  }
}
```

